-- 0134 — vocabulary a second real library named, and the ontology lacked.
--
-- **Generated by `tools/seed_from_csv.py --from 0.9.0 --to 0.10.0`; do not
-- hand-edit the inserts.** To change what is here, edit
-- `semantic/ontology/youtube_terms_*.csv` and regenerate. Two blocks *are*
-- hand-added and are marked: the resolvability assertion and the recompute
-- enqueue, neither of which the generator emits.
--
-- **Why a third CSV family rather than rows in `seed_*.csv`.** Those three
-- files mirror `0044_semantic_seed.sql` exactly and `test_seed_consistency`
-- asserts it field for field; sports were added to them once and broke the
-- mirror by 66 differences. Anything authored since gets its own family.
--
-- **What prompted it.** A second real account connected seven sources on
-- 2026-08-13 and the pipeline produced **zero assertions**. Nothing failed —
-- nine worker jobs succeeded, `rejected 0`. The resolver hit 12 of 20 YouTube
-- topics and **3 of 152 uploader tags**. Checked against 20 of the artists it
-- named, exactly two existed: the creator vocabulary is one person's Apple
-- Music library, minted by `0075`, and it does not generalise to anybody else.
--
-- **This fixes one account and does not fix the problem**, which is worth
-- stating plainly in the place somebody will look. The machinery for automatic
-- growth exists and is switched off at four independent points:
-- `EmergentTermMiner` is unwired and would reject every music term anyway
-- (`safe_for_global_mining=False` at `aws/worker/resolve.py`), `WikidataProvider`
-- is never constructed with providers, `allow_external_resolution` is written
-- as a literal `false` by every ingestion path, and `online_resolution_policy`
-- is read by no code at all. `semantic/README.md`'s cold-start table expects
-- hand curation at this scale and the miner at 20-35 users; this is that.
--
-- **Deliberately not minted**, each for a reason:
--   * the four ONE OK ROCK member names — aliasing a member to the band is the
--     merge `0091` had to undo for nine Korean creators
--   * `阿信` — Mayday's vocalist, a person, not an alias of the band
--   * bare `Eve` — too generic to alias without collecting strangers
--   * `Health`, `Religion`, `Society` — refused by `refusedTopics` as protected
--     characteristics; their absence is correct
--   * roughly half the unresolved tags — `golw`, `Oz.`, `hands`, `matches` —
--     which are not vocabulary at any scale
--
-- **One trap the generator sets.** It computes `normalized_label` as
-- `alias.strip().lower()`, while the resolver matches on `normalize_text`,
-- which folds punctuation to spaces. An alias containing punctuation would be
-- stored as `re:zero` and could never match the resolver's `re zero`. Every
-- alias here is punctuation-free for that reason.

-- Vocabulary a second real library named: J-pop and Mandopop creators, three works, two activities, and genre naming variants.
--
-- Generated by `tools/seed_from_csv.py --from 0.9.0 --to 0.10.0`. Do not
-- hand-edit: change `semantic/ontology/*.csv` and regenerate.
--
-- 74 concepts, 116 labels, 66 edges — the
-- whole hand-authored core, not only what is new. Every insert is
-- `on conflict do nothing` and 0.10.0 copies 0.9.0 forward first, so re-stating
-- an existing concept is a no-op.
--
-- A published ontology version is immutable, so this mints 0.10.0 from 0.9.0 and
-- publishes last — publishing is also retiring, since only one version may be
-- published at a time.

begin;

select gen_random_uuid(), '0.10.0', v.id, 'draft', 'Vocabulary a second real library named: J-pop and Mandopop creators, three works, two activities, and genre naming variants.', null
from ontology.versions v where v.version = '0.9.0'
on conflict (version) do nothing;

select new_v.id, r.concept_id, r.preferred_label, r.concept_kind, r.definition, r.sensitivity, r.inference_policy, r.status, r.metadata
from ontology.concept_revisions r
join ontology.versions old_v on old_v.id = r.ontology_version_id and old_v.version = '0.9.0'
cross join (select id from ontology.versions where version = '0.10.0') new_v
on conflict do nothing;

select new_v.id, l.concept_id, l.label, l.normalized_label, l.locale, l.label_type, l.provenance_type, l.confidence, l.status, l.external_ref
from ontology.concept_labels l
join ontology.versions old_v on old_v.id = l.ontology_version_id and old_v.version = '0.9.0'
cross join (select id from ontology.versions where version = '0.10.0') new_v
on conflict do nothing;

select new_v.id, e.subject_concept_id, e.predicate_key, e.object_concept_id, e.confidence, e.provenance_type, e.provenance, e.status
from ontology.concept_edges e
join ontology.versions old_v on old_v.id = e.ontology_version_id and old_v.version = '0.9.0'
cross join (select id from ontology.versions where version = '0.10.0') new_v
on conflict do nothing;

  id, ontology_version_id, rule_key, evidence_target_concept_id, output_concept_id,
  evidence_predicate_key, output_predicate_key, rule_kind,
  minimum_independence_groups, minimum_strength, configuration, status)
select gen_random_uuid(), new_v.id, m.rule_key, m.evidence_target_concept_id,
       m.output_concept_id, m.evidence_predicate_key, m.output_predicate_key,
       m.rule_kind, m.minimum_independence_groups, m.minimum_strength,
       m.configuration, m.status
from ontology.motif_rules m
join ontology.versions old_v on old_v.id = m.ontology_version_id and old_v.version = '0.9.0'
cross join (select id from ontology.versions where version = '0.10.0') new_v
on conflict do nothing;

create temporary table seed_concept (concept_key text primary key, preferred_label text not null, concept_kind text not null, sensitivity text not null, inference_policy text not null, status text not null) on commit drop;

create temporary table seed_label (concept_key text, label text, normalized_label text, locale text, label_type text) on commit drop;

create temporary table seed_edge (subject_key text, predicate_key text, object_key text, confidence double precision, status text) on commit drop;

select gen_random_uuid(), s.concept_key from seed_concept s
on conflict (concept_key) do nothing;

-- **`inference_policy` comes from the CSV, never from a default here.** Every
-- sport is `review_required`, which is the whole reason the column exists: a
-- fitness activity implies something about somebody's body and a watched match
-- implies far less than it looks like it does. Hardcoding `inferable` in the
-- generator would erase a per-concept decision at the point it is written down.
  ontology_version_id, concept_id, preferred_label, concept_kind,
  definition, sensitivity, inference_policy, status, metadata)
select v.id, c.id, s.preferred_label, s.concept_kind, null,
       s.sensitivity, s.inference_policy, s.status, '{}'::jsonb
from seed_concept s
join ontology.concepts c on c.concept_key = s.concept_key
cross join (select id from ontology.versions where version = '0.10.0') v
on conflict (ontology_version_id, concept_id) do nothing;

  ontology_version_id, concept_id, label, normalized_label, locale,
  label_type, provenance_type, confidence, status)
select v.id, c.id, l.label, l.normalized_label, l.locale,
       l.label_type, 'curated', 1.0, 'active'
from seed_label l
join ontology.concepts c on c.concept_key = l.concept_key
cross join (select id from ontology.versions where version = '0.10.0') v
on conflict (ontology_version_id, concept_id, locale, normalized_label, label_type)
  do nothing;

  ontology_version_id, subject_concept_id, predicate_key, object_concept_id,
  confidence, provenance_type, provenance, status)
select v.id, subject.id, e.predicate_key, object.id, e.confidence, 'curated',
       '{"source": "seed_csv"}'::jsonb, e.status
from seed_edge e
join ontology.concepts subject on subject.concept_key = e.subject_key
join ontology.concepts object on object.concept_key = e.object_key
cross join (select id from ontology.versions where version = '0.10.0') v
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Hand-added: resolvability, in the style of `0096`.
-- ---------------------------------------------------------------------------
--
-- **About whether the terms resolve, not about how many there are.** Counting
-- the right number of unreachable things is the failure mode of a structural
-- check — `0095` minted 35 concepts that could never resolve and passed its own
-- assertion. This asks the question the resolver asks: does each new concept
-- carry an auto-accepting label (`preferred` or `alternate`) whose
-- `normalized_label` is what a term would normalise to?
--
-- It must also hold on an empty database, since
-- `tools/ci/unreplayable_migrations.txt` is empty and is to stay that way, so
-- it asserts nothing about production rows.

do $$
declare
  unreachable text;
  missing_music_form text;
begin
  select string_agg(c.concept_key, ', ' order by c.concept_key)
    into unreachable
  from ontology.concepts c
  join ontology.concept_revisions cr on cr.concept_id = c.id
  join ontology.versions v on v.id = cr.ontology_version_id and v.version = '0.10.0'
  where c.concept_key in (
    'creator:one_ok_rock', 'creator:gen_hoshino', 'creator:taichi_mukai',
    'creator:jolin_tsai', 'creator:eve_ai', 'creator:xiao_yu',
    'creator:nariaki_obukuro', 'creator:akko_gorilla', 'creator:sufjan_stevens',
    'creator:corsak', 'work:ranking_of_kings', 'work:run_with_the_wind',
    'work:call_me_by_your_name', 'activity:flute',
    'activity:quantitative_research'
  )
  and not exists (
    select 1 from ontology.concept_labels cl
    where cl.concept_id = c.id
      and cl.ontology_version_id = v.id
      and cl.status = 'active'
      and cl.label_type in ('preferred', 'alternate')
  );
  if unreachable is not null then
    raise exception 'these would resolve to nothing: %', unreachable;
  end if;

  -- The specific miss that started this: YouTube states topics as `Rock_music`,
  -- which `normalize_text` gives as `rock music`, and `genre:rock` carried only
  -- `rock`. Asserted by name because it is the one case measured end to end.
  select string_agg(want.term, ', ' order by want.term) into missing_music_form
  from (values ('rock music'), ('hip hop music'), ('soul music')) as want(term)
  where not exists (
    select 1 from ontology.concept_labels cl
    join ontology.versions v on v.id = cl.ontology_version_id and v.version = '0.10.0'
    where cl.normalized_label = want.term and cl.status = 'active'
  );
  if missing_music_form is not null then
    raise exception 'YouTube topic forms still unresolvable: %', missing_music_form;
  end if;

  raise notice '0134: 15 concepts and their labels are resolvable at 0.10.0';
end
$$;

update ontology.versions set status = 'retired'
 where version = '0.9.0' and status = 'published';

update ontology.versions set status = 'published', published_at = now()
 where version = '0.10.0';


-- ---------------------------------------------------------------------------
-- Hand-added: the recompute. `seed_from_csv.py` does not emit this.
-- ---------------------------------------------------------------------------
--
-- **A migration that publishes an ontology version ends here.** Ingestion is
-- the only other thing that enqueues and it cannot see a publish, so without
-- this the system changes what it *would* compute and nothing it has. `0096`
-- omitted it and `0097` exists solely to pay that debt.
--
-- The queue does not drain itself: `written-semantic-worker` must be invoked
-- serially until it answers `{"claimed": false}`.

do $$
declare
  enqueued integer;
begin
  select semantic_private.enqueue_recompute_on_analysis_change(
    'ontology 0.10.0: creators, works and activities a second library named'
  ) into enqueued;
  raise notice 'enqueued % recompute job(s) for ontology 0.10.0', enqueued;
end
$$;

commit;
